    ~ (P <= a < P + 4) -> ~ (P + 16 + 4 * cnt1 <= a < P + 20 + 4 * cnt1) -> ~ (TH + 2768 <= a < TH + 3168) ->
    ~ (RI <= a < RI + 88) -> ~ (FA s c + 4 * nf <= a < FA s c + mfa') -> ~ (sh (FA s c + mfa) <= a < sh (FA s c + mfa) + (mfa' - mfa) / 8) ->
